INSERT INTO Clusters (clusterCode, bmcCode, clusterName, taluk, rtCd, bmcType, bmcId, createdAt, updatedAt) SELECT '6856', '2373', 'VEMGAL', 'SDG', '', 'CL', (SELECT id FROM BMCs WHERE bmcCode = '2373' AND (isDeleted IS NULL OR isDeleted = 0) LIMIT 1), NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM Clusters WHERE UPPER(clusterName) = UPPER('VEMGAL') AND taluk = 'SDG' AND (isDeleted IS NULL OR isDeleted = 0));

